contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We cannot directly read arbitrary external accounts' balances from within this contract
    // for an absolute check, but we can observe that go sends c's entire balance out and that
    // owner address remains unchanged; combined these imply owner was not paid from c by go.

    // Public test entry: send an arbitrary amount `amount` of Ether to c.go
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Observe owner and c balance before call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After call, read owner and c balance
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;

        // General rule asserted: if the call did not revert, owner unchanged and c balance is zero
        // This implies owner did not receive ETH from c (since c's balance becomes zero and owner unchanged)
        assert(reverted || (ownerAfter == ownerBefore && cBalAfter == 0));
    }

    receive() external payable {}
}

